insert into public.kpi_benchmarks (key, product, value, low, high, source, source_url, as_of, note) values
  ('store_tap_through', 'parent', null, 6.0, 12.0, 'Adapty, App Store conversion rate benchmarks', 'https://adapty.io/blog/app-store-conversion-rate/', '2026-01', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Arama sonuçlarında gösterim → ürün sayfası (CTR) aralığı, genel değer; medyan verilmemiş, low/high kaynaktaki aralık (çeyrek değil). Apple App Analytics''te ürün sayfası görüntüleme / tekil cihaz gösterimi olarak hesaplanır; göz atma (browse) gösterimleri de sayıldığı için oran düşebilir. Education / Lifestyle / Health & Fitness için ayrı değer bu'),
  ('store_tap_through', 'clinic', null, 6.0, 12.0, 'Adapty, App Store conversion rate benchmarks', 'https://adapty.io/blog/app-store-conversion-rate/', '2026-01', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Arama sonuçlarında gösterim → ürün sayfası (CTR) aralığı, genel değer; medyan verilmemiş, low/high kaynaktaki aralık (çeyrek değil). Apple App Analytics''te ürün sayfası görüntüleme / tekil cihaz gösterimi olarak hesaplanır; göz atma (browse) gösterimleri de sayıldığı için oran düşebilir. Business / Medical için ayrı değer bulunamadı; Mercek''in ka'),
  ('store_page_conversion', 'parent', 8.56, 5.2, 52.8, 'AppTweak, Average App Conversion Rate per Category [2025]', 'https://www.apptweak.com/en/aso-blog/average-app-conversion-rate-per-category', '2025-12', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. ABD App Store 2025 ortalaması (ilk indirme / ürün sayfası görüntüleme; yeniden indirmeler hariç), genel değer. low/high = en düşük (Oyun-Trivia) ve en yüksek (Yiyecek-İçecek) kategori ortalaması, çeyrek değil. Education ve Lifestyle değeri bulunamadı; Health & Fitness için ikincil sitelerde çelişkili 23,2–30,8. Sık alıntılanan ~%25 (H1 2024) yeni'),
  ('store_page_conversion', 'clinic', 8.56, 5.2, 52.8, 'AppTweak, Average App Conversion Rate per Category [2025]', 'https://www.apptweak.com/en/aso-blog/average-app-conversion-rate-per-category', '2025-12', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Genel ABD App Store 2025 ortalaması; low/high kategori uçları. Business için ikincil sitelerde çelişkili 48,0–66,7 (H1 2024, yeniden indirmeli tanım); güvenilmedi. Web kaydı bu ölçüye girmez. Ay yaklaşık.'),
  ('download_to_signup', 'parent', null, null, null, 'RevenueCat, State of Subscription Apps 2026', 'https://www.revenuecat.com/state-of-subscription-apps', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Tüketici uygulamalarında indirme → hesap açma için güvenilir yayımlanmış kıyas bulunamadı (yalnız kaynaksız satıcı blogları: ''üst düzey uygulamalar >%40''). Yakın ama farklı ölçü: RevenueCat 2026 indirme → mağaza denemesi medyanı Education %6,5, Health & Fitness %6,9; bu, kartlı denemeyi ödeme duvarında başlatmaktır, bizim kayıt (kartsız 14 gün başlar) ücretsiz hesap açmadır, kıyaslanmaz.'),
  ('download_to_signup', 'clinic', null, null, null, 'First Page Sage, SaaS Free Trial Conversion Rate Benchmarks', 'https://firstpagesage.com/seo-blog/saas-free-trial-conversion-rate-benchmarks/', '2025-09', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). B2B mobil indirme → kayıt kıyası bulunamadı. Web tarafı için farklı ama yakın ölçü: First Page Sage ziyaretçi → deneme, kartsız (opt-in) %8,5, kartlı %2,5; Healthcare/Medtech ziyaretçi → deneme %12,3 (deneme türüne göre ayrılmamış). Panelde web ziyaretçisi ölçülüyorsa bunlarla kıyaslanabilir.'),
  ('signup_to_activation', 'parent', null, null, null, 'Userpilot, User Activation Rate Benchmark Report 2024', 'https://userpilot.com/blog/user-activation-for-saas/', '2024-01', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Tüketici uygulaması için yayımlanmış aktivasyon kıyası bulunamadı. Tek kaynak B2B SaaS (Userpilot 2024, 62 şirket: medyan %37, ortalama %37,5); farklı kitle, ebeveyn ürünü için kullanılmadı. Aktivasyon tanımı her üründe kendine özgü olduğundan bu ölçü en iyi kendi geçmişimizle izlenir.'),
  ('signup_to_activation', 'clinic', 37.0, null, null, 'Userpilot, User Activation Rate Benchmark Report 2024', 'https://userpilot.com/blog/user-activation-for-saas/', '2024-01', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. 62 B2B SaaS şirketi, medyan %37 (ortalama %37,5); bir Userpilot yazısı aynı ortalamayı 547 şirkete bağlıyor. Sektör: Healthcare %23,8 (tek ikincil kaynak), AI/ML %54,8, FinTech ~%5. Çeyrekler yok. Aktivasyon tanımı şirkete göre değişir; bizim eşik (ör. ilk aile daveti gönderildi ya da ilk aile bağlandı) daha zorsa düşük çıkması beklenir. Rapor ay'),
  ('trial_to_paid', 'parent', 18.2, null, null, 'First Page Sage, SaaS Free Trial Conversion Rate Benchmarks', 'https://firstpagesage.com/seo-blog/saas-free-trial-conversion-rate-benchmarks/', '2025-09', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kartsız (opt-in) deneme, 86 SaaS şirketi (%71 B2B, %29 B2C), Q1 2022–Q3 2025; ortalama mı medyan mı belirtilmemiş. Kartlı (opt-out) %48,8, ama ziyaretçi → deneme kartsızda %8,5, kartlıda %2,5. Sitenin 2026 baskısı 17,2 / 49,3 diyor (baskıya göre değişiyor). B2C mobil kartsız deneme için güvenilir kıyas yok; en yakın bu SaaS değeri. Mobil kıyasların neredeyse hepsi mağazanın kartlı denemesidir (iptal edilmeyen ücretli sayı'),
  ('trial_to_paid', 'clinic', 18.2, null, null, 'First Page Sage, SaaS Free Trial Conversion Rate Benchmarks', 'https://firstpagesage.com/seo-blog/saas-free-trial-conversion-rate-benchmarks/', '2025-09', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kartsız (opt-in) deneme, 86 SaaS şirketi (%71 B2B, %29 B2C), Q1 2022–Q3 2025; ortalama mı medyan mı belirtilmemiş. Kartlı (opt-out) %48,8, ama ziyaretçi → deneme kartsızda %8,5, kartlıda %2,5. Sitenin 2026 baskısı 17,2 / 49,3 diyor (baskıya göre değişiyor). Healthcare/Medtech deneme → ücretli %21,5 (kartlı/kartsız ayrılmamış). Lenny''s Newsletter / K. Poyar (1.000+ ürün): deneme ürünlerinde en sık aralık %7,5–10 (6 ay için'),
  ('monthly_churn', 'parent', null, null, null, 'RevenueCat, State of Subscription Apps 2026', 'https://www.revenuecat.com/state-of-subscription-apps', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). App Store tüketici aboneliği için ''aylık kayıp'' olarak yayımlanmış medyan bulunamadı. Bağlam: aylık planda ilk yenileme Education medyanı %56 (yani ilk ayda ~%44 kayıp); aylık planların 12 ay sonraki elde tutması medyan %9,5 (AI dışı, RevenueCat 2026; eski RevenueCat yazısı %11, çeyrekler 5–19) — ortalama ~%17/ay kayba denk gelir (bizim hesabımız, kaynakta yazan sayı değil). Web faturalı aboneliklerde Recurly Education %4'),
  ('monthly_churn', 'clinic', 3.22, null, null, 'Recurly, Churn rate benchmarks', 'https://recurly.com/research/churn-rate-benchmarks/', '2026-07', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. SaaS toplam kayıp medyanı (gönüllü 2,16 + ödeme kaynaklı 1,06), Recurly ağı, web faturası, Temmuz 2026 verisi. İkincil siteler bu sayfanın değerlerini kimi zaman ''yıllık'' diye etiketliyor; aylık oran olarak okundu, doğrulanmadı. ChartMogul (2022): müşteri başı aylık gelir <25 $ olanlarda medyan aylık müşteri kaybı %6,1, >500 $ olanlarda %1,9–2,2;'),
  ('monthly_renewal_m1', 'parent', 56.0, 48.0, 66.0, 'RevenueCat, Average Subscription Renewal Rates by App Category (2026 Benchmarks)', 'https://www.revenuecat.com/blog/growth/average-subscription-renewal-rates-by-app-category', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Education kategorisi medyanı; low/high = 25. ve 75. yüzdelik. Health & Fitness 46 / 57 / 68; Social & Lifestyle 27 / 42 / 61. Bütün kategorilerde medyanlar %53–61. Kartlı mağaza denemesinden gelen aboneler dahil. RevenueCat SOSA 2026 verisi; yazının yayın ayı doğrulanmadı.'),
  ('monthly_renewal_m1', 'clinic', 61.0, 49.0, 74.0, 'RevenueCat, Average Subscription Renewal Rates by App Category (2026 Benchmarks)', 'https://www.revenuecat.com/blog/growth/average-subscription-renewal-rates-by-app-category', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Business kategorisi medyanı (bütün kategoriler içinde en yüksek); low/high = 25. ve 75. yüzdelik. Mercek App Store üzerinden RevenueCat ile satıldığı için web SaaS kıyasından daha uygun.'),
  ('annual_renewal', 'parent', 24.0, 17.0, 32.0, 'RevenueCat, Average Subscription Renewal Rates by App Category (2026 Benchmarks)', 'https://www.revenuecat.com/blog/growth/average-subscription-renewal-rates-by-app-category', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Education medyanı (kategoriler içinde zayıf); low/high = 25. ve 75. yüzdelik. Health & Fitness 16 / 25 / 37; bütün kategorilerde medyan %23–40. RevenueCat 2026: yıllık iptallerin %35''i ilk ayda; iptal eden yıllık abonelerin %95''i geri dönmüyor. 13. aya kadar ölçülemez.'),
  ('annual_renewal', 'clinic', 40.0, 21.0, 53.0, 'RevenueCat, Average Subscription Renewal Rates by App Category (2026 Benchmarks)', 'https://www.revenuecat.com/blog/growth/average-subscription-renewal-rates-by-app-category', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Business medyanı (Travel ile birlikte en yüksek); low/high = 25. ve 75. yüzdelik. 13. aya kadar ölçülemez.'),
  ('annual_share', 'parent', null, 59.0, 66.0, 'RevenueCat, State of Subscription Apps 2026', 'https://www.revenuecat.com/state-of-subscription-apps', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Education, Travel ve Shopping''de yıllık plan payı %59–66 (RevenueCat 2026; abone payı mı gelir payı mı özetlerde net değil); medyan verilmemiş, low/high kategori aralığı. Health & Fitness''ta yıllık gelir payı %68 (RevenueCat) ya da %60,6 (Adapty 2026). Kıyaslar haftalık planları da içerir; bizde haftalık plan yok.'),
  ('annual_share', 'clinic', 20.7, null, null, 'RevenueCat, Annual subscriptions for apps: The pros and cons (SOSA verisi)', 'https://www.revenuecat.com/blog/growth/annual-subscriptions-apps-pros-cons/', '2025-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Business kategorisinde satılan aboneliklerin %20,7''si yıllık (haftalık ~%44,7, aylık ~%34,4 ile birlikte); bir başka RevenueCat yazısı %20,6. Hangi SOSA baskısı olduğu ve ay doğrulanmadı. Mercek''te haftalık plan yok; yalnız aylık + yıllık içinde pay daha yüksek olur (hesap, kaynak değil). Web B2B SaaS için yayımlanmış yıllık plan payı kıyası bulu'),
  ('refund_rate', 'parent', 4.86, 1.51, 4.86, 'RevenueCat, State of Subscription Apps 2025', 'https://www.revenuecat.com/state-of-subscription-apps-2025', '2025-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Education iade oranı (ilk fatura döneminde iade edilen ücretli abonelik payı), 2025 raporu (2024 verisi); kategoriler içinde en yüksek, Health & Fitness 4,71. low/high = en düşük (Travel 1,51) ve en yüksek kategori. 2026 raporu: AI dışı medyan %3,5 (AI %4,2), kategorilerin çoğu %3–4, en yüksek Productivity %4,7, en düşük Travel %2,5; Education 20'),
  ('refund_rate', 'clinic', 3.5, 2.5, 4.7, 'TechCrunch, RevenueCat SOSA 2026 haberi', 'https://techcrunch.com/2026/03/10/ai-powered-apps-struggle-with-long-term-retention-new-report-shows', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). RevenueCat 2026, AI dışı uygulamalar medyanı (TechCrunch üzerinden); low/high = kategori medyanlarının en düşüğü (Travel) ve en yükseği (Productivity). Business 2025 raporunda ortalamanın altında (Gaming ile birlikte 2,67–2,88), 2026''da yüksek iade kategorileri arasında anılıyor. Tanım: ilk fatura döneminde iade edilen ücretli abonelik payı. Düşük olan iyidir.'),
  ('billing_issue_rate', 'parent', 15.2, null, null, 'RevenueCat, State of Subscription Apps 2026', 'https://www.revenuecat.com/state-of-subscription-apps', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. TANIM FARKI: App Store''da iptallerin %15,2''si ödeme hatasından (istem dışı kayıp); 2025 raporu %15,1, bir özet %14; Google Play ~%31–32. Yenilemelerin ya da aktif aboneliklerin yüzde kaçının ödeme sorununa düştüğüne dair kamuya açık kıyas bulunamadı; panel oranı öyle tanımlıysa bu sayı kıyaslanmaz. Düşük olan iyidir.'),
  ('billing_issue_rate', 'clinic', 15.2, null, null, 'RevenueCat, State of Subscription Apps 2026', 'https://www.revenuecat.com/state-of-subscription-apps', '2026-03', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. TANIM FARKI: App Store''da iptallerin %15,2''si ödeme hatasından (istem dışı kayıp); 2025 raporu %15,1, bir özet %14; Google Play ~%31–32. Yenilemelerin ya da aktif aboneliklerin yüzde kaçının ödeme sorununa düştüğüne dair kamuya açık kıyas bulunamadı; panel oranı öyle tanımlıysa bu sayı kıyaslanmaz. Düşük olan iyidir. Mercek de App Store''dan fatur'),
  ('d1_retention', 'parent', 26.0, null, null, 'Adjust, The app user retention handbook', 'https://www.adjust.com/resources/guides/user-retention/', '2024-04', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Bütün kategoriler, küresel medyan, kuruluma göre tam gün geri dönüş; genel değer, çeyrekler yok. Health & Fitness 1. gün %27 (eski Adjust yazısı). AppsFlyer iOS %23,9 (Q3 2024, ikincil). Eğitim için ikincil kaynaklarda %14–15. Tarih ikincil kaynağa göre. Bizde ölçüm kayıttan ya da ilk açılıştan başlıyorsa değerler kurulum tabanlı kıyastan yüksek '),
  ('d7_retention', 'parent', 13.0, null, null, 'Adjust, The app user retention handbook', 'https://www.adjust.com/resources/guides/user-retention/', '2024-04', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Küresel medyan; iOS %14, Android %11 (Adjust). AppsFlyer iOS %8,3 (ikincil). Lifestyle 1/7/30. gün 25/13/6 (ikincil, kaynağı doğrulanmadı).'),
  ('d30_retention', 'parent', 7.0, null, null, 'Adjust, The app user retention handbook', 'https://www.adjust.com/resources/guides/user-retention/', '2024-04', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). Kaynak sayfası bu oturumda açılamadı (ağ izni); sayı arama özetinden alındı. Küresel medyan (Adjust). AppsFlyer iOS %3,7 (Q3 2024, ikincil); Eğitim 30. gün %2–3 (AppsFlyer''a atfedilen ikincil). Türkiye: Adjust 2025''te finans uygulamalarında 30. gün %5 (MENAT %4, küresel %2) — başka kategori, kıyas için değil.'),
  ('d1_retention', 'clinic', null, null, null, 'Amplitude, Product benchmarks / The 7% Retention Rule', 'https://amplitude.com/blog/7-percent-retention-rule', '2025-06', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). B2B SaaS''ta kayıtlı kullanıcı için gün bazında yayımlanmış kıyas bulunamadı. Amplitude (bütün ürünler, ''yeni kullanıcı'' = anonim web ziyaretçileri dahil) 7. gün medyanı ~%2 (P75 %5,6, P90 %12,4); ''%7 kuralı'': 7. günde kohortun ≥%7''si dönüyorsa ürün aktivasyonda üst çeyrekte. Payda farklı olduğu için kayıtlı uzmanların oranıyla kıyaslanmaz. Uzman ürünü iş günü ritmiyle kullanılır; 1. gün en zayıf sinyaldir.'),
  ('d7_retention', 'clinic', null, null, null, 'Amplitude, Product benchmarks / The 7% Retention Rule', 'https://amplitude.com/blog/7-percent-retention-rule', '2025-06', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). B2B SaaS''ta kayıtlı kullanıcı için gün bazında yayımlanmış kıyas bulunamadı. Amplitude (bütün ürünler, ''yeni kullanıcı'' = anonim web ziyaretçileri dahil) 7. gün medyanı ~%2 (P75 %5,6, P90 %12,4); ''%7 kuralı'': 7. günde kohortun ≥%7''si dönüyorsa ürün aktivasyonda üst çeyrekte. Payda farklı olduğu için kayıtlı uzmanların oranıyla kıyaslanmaz. Kendi kohort geçmişimizle izlenmesi önerilir.'),
  ('d30_retention', 'clinic', null, null, null, 'Amplitude, Product benchmarks / The 7% Retention Rule', 'https://amplitude.com/blog/7-percent-retention-rule', '2025-06', 'Arama özetinden alındı, kaynak sayfa bu ortamdan açılamadı (doğrulanmadı). B2B SaaS''ta kayıtlı kullanıcı için gün bazında yayımlanmış kıyas bulunamadı. Amplitude (bütün ürünler, ''yeni kullanıcı'' = anonim web ziyaretçileri dahil) 7. gün medyanı ~%2 (P75 %5,6, P90 %12,4); ''%7 kuralı'': 7. günde kohortun ≥%7''si dönüyorsa ürün aktivasyonda üst çeyrekte. Payda farklı olduğu için kayıtlı uzmanların oranıyla kıyaslanmaz. Amplitude 2024: sağlık ürünlerinde 1. ay elde tutma %14 (ay bazında, farklı tanım).')
